<?php require __DIR__.'/../config/bootstrap.php';require_role('admin');$rows=$pdo->query("SELECT e.*,u.full_name,u.email,c.title,p.reference,p.provider,p.amount_kes FROM enrollments e JOIN users u ON u.id=e.user_id JOIN courses c ON c.id=e.course_id JOIN payments p ON p.id=e.payment_id ORDER BY e.enrolled_at DESC")->fetchAll();$page_title='Enrollments';require __DIR__.'/../includes/header.php';?>
<h1 class="text-3xl font-bold">Course enrollments</h1><div class="overflow-x-auto bg-white border rounded-xl mt-6"><table class="w-full text-sm"><thead class="bg-slate-100"><tr><?php foreach(['Student','Email','Course','Payment method','Amount','Status','Date'] as $h): ?><th class="p-3 text-left"><?= $h ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($rows as $r): ?><tr class="border-t"><td class="p-3"><?= e($r['full_name']) ?></td><td class="p-3"><?= e($r['email']) ?></td><td class="p-3"><?= e($r['title']) ?></td><td class="p-3"><?= e($r['provider']) ?></td><td class="p-3"><?= money((int)$r['amount_kes']) ?></td><td class="p-3"><?= e($r['status']) ?></td><td class="p-3"><?= e($r['enrolled_at']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php require __DIR__.'/../includes/footer.php';?>
